// The Streaming Row Unit's datapath and sequencer, between a word stream in
// and a word stream out. docs/projects/kohakutpu/sru.md is the design; the
// configuration map is sru_cfg.vh (generated by scripts/py/sru/cfg.py).
//
// A JOB is NSR sub-rows of NW words (4 x 4 FP16 sub-tiles, lane 4r + c). Each
// sub-row runs the job's passes:
//
//   BUF = 0  pass 0 only, straight from stream A (and B), through the chain.
//   BUF = 1  pass 0 fills the sub-row buffer from A (R1 taps it); passes
//            1..NPASS replay the buffer through the chain. Fill of sub-row
//            g+1 overlaps the replays of g.
//
// CHAIN: unpack -> mask -> POOL -> R2 -> FP16 -> (MXFP7) -> out. The pool
// (sru_pool) runs the pass's program of NOPS ops on every element, taking a
// word at each of its windows (II cycles); a pass of no ops passes the word
// through, a word a cycle. Only one pass is in the chain at a time (the issuer
// drains it when the pass changes, and the pool restarts on the new program).
//
// ROW STATE: three scalars a row (R0..R2) in a 512 x 72 RAM, loaded into a
// working set W per sub-row (double-buffered by sub-row parity, words carry
// their parity) and stored back after it. The FINALISE runs a pass's program
// of scalar ops (MOV, ADD, SUB, MUL, FMA, MAX, MIN; RCP, RSQRT with FIN_RCP)
// over the sub-row's 4 rows once the pass's statistics land: sources R0..R2,
// T, ST1 (R1's row max), ST2 (R2's row sum), K0..K3.
//
// FP16 (F16_IEEE): 1 IEEE in and out (subnormals, inf / NaN); 0 the clusters'
// accumulator form: exponent 0 is zero, 31 an ordinary binade in; out rounds to
// nearest even, flushes below 2^-14 and saturates at 65504 (mx_fpacc_to_fp16).
//
// OUTPUT is credited: a word is issued only while the out FIFO has room for
// every word in flight, so nothing inside ever stalls.
//
// Contracts: NW >= 4 when R2 feeds a finalise; NW a multiple of 8 for MXFP7
// out; NW <= BUF_WORDS / 2 when buffered; stream B only on unbuffered jobs.

`default_nettype none

(* shreg_extract = "no" *)
module sru_core #(
    parameter integer MODEL     = 0,
    parameter integer F_LANES   = 16,      // pool lanes: 16 | 8 | 4, 0 = no pool
    parameter integer HAS_FN    = 1,       // function front ends on the lanes
    parameter         TAB       = "ram",   // "ram" | "rom" (exp2 only)
    parameter integer H_TAPS    = 2,       // earlier results an op may read: 1 | 2
    parameter integer HAS_R1    = 1,
    parameter integer HAS_R2    = 1,
    parameter integer HAS_MX7   = 1,
    parameter integer MX_DSP    = 1,
    parameter integer HAS_MASK  = 1,
    parameter integer HAS_B     = 1,       // stream B
    parameter integer BUF_WORDS = 512,     // 0: no buffer; halves of BUF_WORDS/2
    parameter integer OUT_DEPTH = 64,
    parameter integer HAS_MANT  = 0,       // MANT / HALF function modes (RAM table)
    parameter integer FIN_RCP   = 0,       // finalise RCP / RSQRT (lane 0's ROM)
    parameter integer F16_IEEE  = 1        // FP16 in / out: IEEE (1), accumulator form (0)
)(
    input  wire          clk,
    input  wire          rst,

    input  wire          cfg_we,
    input  wire [7:0]    cfg_addr,
    input  wire [31:0]   cfg_wdata,

    input  wire          tab_we,
    input  wire [9:0]    tab_waddr,
    input  wire [35:0]   tab_wdata,

    input  wire          cc_we,
    input  wire [8:0]    cc_waddr,
    input  wire [191:0]  cc_wdata,     // 4 columns x {C1, C0}, E8M15; column c at [48c +: 48]

    input  wire          rs_we,
    input  wire [8:0]    rs_waddr,
    input  wire [71:0]   rs_wdata,     // {R2, R1, R0}, E8M15
    input  wire [8:0]    rs_raddr,
    output wire [71:0]   rs_rdata,

    input  wire          start,
    output reg           busy,
    output reg           done,

    input  wire          a_valid,
    input  wire [255:0]  a_data,
    output wire          a_ready,
    input  wire          b_valid,
    input  wire [255:0]  b_data,
    output wire          b_ready,

    output wire          o_valid,
    output wire [255:0]  o_data,
    output wire [7:0]    o_count,      // words in the out FIFO
    input  wire          o_pop
);
    `include "sru_cfg.vh"
    `include "sru_f16e8.vh"

    localparam integer BUFA = (BUF_WORDS > 4) ? $clog2(BUF_WORDS) : 2;
    localparam integer OAW  = $clog2(OUT_DEPTH);
    localparam integer OCW  = OAW + 3;
    integer i, q;
    genvar  gk;

    // ======================================================== configuration
    reg [31:0] cfg [0:(1 << `SRU_CFG_AW) - 1];
    always @(posedge clk) begin
        if (cfg_we) begin
            cfg[cfg_addr] <= cfg_wdata;
        end
    end

    wire [11:0] c_nw    = `SRU_G_NW;
    wire [1:0]  c_npass = `SRU_G_NPASS;
    wire        c_buf   = (BUF_WORDS > 0) && `SRU_G_BUF;
    wire        c_useb  = (HAS_B != 0) && `SRU_G_USE_B;
    wire [1:0]  c_outf  = `SRU_G_OUT;
    wire [1:0]  c_out   = (HAS_MX7 != 0) ? c_outf : {1'b0, (c_outf != 2'd0)};
    wire        c_mask  = (HAS_MASK != 0) && `SRU_G_MASK;
    wire        c_r1    = (HAS_R1 != 0) && `SRU_G_R1;
    wire [15:0] c_nsr   = `SRU_G_NSR;
    wire [8:0]  c_row0  = `SRU_G_ROW0;
    wire [8:0]  c_col0  = `SRU_G_COL0;
    wire [15:0] c_dhi   = `SRU_G_DHI;
    wire [15:0] c_clim  = `SRU_G_CLIM;
    wire [23:0] c_mval  = `SRU_G_MVAL;
    wire [15:0] c_coff  = `SRU_G_COLOFF;
    wire [15:0] c_roff  = `SRU_G_ROWOFF;
    wire        mx      = c_out[1];
    wire        op_we   = cfg_we && (cfg_addr[7:6] == 2'b01);

    // ======================================================== sequencer state
    localparam [3:0] S_IDLE = 4'd0, S_SR = 4'd1, S_LOAD = 4'd2, S_FIN = 4'd3,
                     S_PASS = 4'd4, S_ISSUE = 4'd5, S_NEXT = 4'd6, S_PWAIT = 4'd7,
                     S_STORE = 4'd8, S_DRAIN = 4'd9;
    reg  [3:0]  st;
    reg  [15:0] g;                     // sub-row the chain is on
    reg  [1:0]  p;                     // its pass
    reg  [11:0] wi;                    // word issued in this pass
    reg  [1:0]  cur;                   // pass in the chain
    reg         fin_then_pass;         // after the finalise: the next pass (1) or store (0)
    reg  [2:0]  ld;
    wire        par = g[0];

    // ======================================================== stream A side
    reg  [15:0] gf;                    // sub-row the fill is on
    reg  [11:0] wf;                    // word in it
    reg  [1:0]  filled;                // a half holds a whole sub-row not yet released
    wire        fh = gf[0];
    wire        fill_on   = busy && c_buf && (gf < c_nsr) && !filled[fh];
    wire        fill_take = fill_on && a_valid;

    reg  [OCW-1:0] res;                // out-FIFO reservation, in input words
    wire [OCW-1:0] res_max = mx ? (OUT_DEPTH * 2) : OUT_DEPTH;
    wire        emit_p  = `SRU_P_EMIT(p) && (c_out != 2'd0);
    wire        credit  = !emit_p || (res < res_max);
    wire        can_d   = a_valid && (!c_useb || b_valid);
    // the pass in the chain: through the pool, or straight through
    wire [3:0]  nops_c  = (F_LANES != 0) ? `SRU_P_NOPS(cur) : 4'd0;
    wire        use_pl  = (nops_c != 4'd0);
    wire        pl_want;
    wire        slot    = !use_pl || pl_want;
    wire        issue   = (st == S_ISSUE) && credit && slot && (c_buf || can_d);
    wire        d_take  = (st == S_ISSUE) && !c_buf && credit && slot && can_d;
    wire        d_first = (wi == 12'd0);
    wire        d_last  = (wi == c_nw - 12'd1);
    assign a_ready = fill_on || d_take;
    assign b_ready = d_take && c_useb;

    wire [255:0]   buf_rd;
    wire [BUFA-1:0] buf_ra = {par, wi[BUFA-2:0]};
    generate
    if (BUF_WORDS > 0) begin : g_buf
        kohaku_sdpram #(.WIDTH(256), .DEPTH(BUF_WORDS), .MEM_PRIM("block"), .READ_LAT(2)) u_buf (
            .clk(clk),
            .wr_en(fill_take), .wr_addr({fh, wf[BUFA-2:0]}), .wr_data(a_data),
            .rd_en(1'b1), .rd_addr(buf_ra), .rd_data(buf_rd)
        );
    end else begin : g_nobuf
        assign buf_rd = 256'd0;
    end
    endgenerate

    // R1: row max on FP16, on whichever A words enter (filled or issued)
    wire        r1_in    = fill_take || d_take;
    wire        r1_first = fill_take ? (wf == 12'd0) : d_first;
    wire        r1_last  = fill_take ? (wf == c_nw - 12'd1) : d_last;
    wire        r1_ovalid;
    wire [231:0] r1_out;
    generate
    if (HAS_R1 != 0) begin : g_r1
        sru_red #(.KIND("max"), .EW(16)) u_r1 (
            .clk(clk), .rst(rst), .in_valid(r1_in && c_r1), .in_first(r1_first),
            .in_last(r1_last), .in_data({128'd0, a_data}),
            .out_valid(r1_ovalid), .out(r1_out)
        );
    end else begin : g_nor1
        assign r1_ovalid = 1'b0;
        assign r1_out = 232'd0;
    end
    endgenerate

    // ======================================================== issue -> +4
    // +2: the word (buffer or the registered input) and its column constants
    reg  [255:0] ia1, ia2, ib1, ib2;
    reg  [4:0]   im1, im2, im3, m4;    // {first, last, par, emit, valid}
    reg  [11:0]  ih1, ih2, ih3;
    reg  [15:0]  ig1, ig2, ig3;
    always @(posedge clk) begin
        ia1 <= a_data;
        ia2 <= ia1;
        ib1 <= b_data;
        ib2 <= ib1;
        if (rst) begin
            im1 <= 5'd0; im2 <= 5'd0; im3 <= 5'd0;
        end else begin
            im1 <= {d_first, d_last, par, emit_p, issue};
            im2 <= im1;
            im3 <= im2;
        end
        ih1 <= wi;  ih2 <= ih1;
        ig1 <= g;   ig2 <= ig1;
    end
    wire [255:0] fa2 = c_buf ? buf_rd : ia2;

    // column constants, E8M15: column c at [48c +: 48] = {C1, C0}; the pool
    // reads them per op
    wire [191:0] cc_rd;
    wire [8:0]   cc_ra;
    kohaku_sdpram #(.WIDTH(192), .DEPTH(512), .MEM_PRIM("block"), .READ_LAT(2)) u_cc (
        .clk(clk), .wr_en(cc_we), .wr_addr(cc_waddr), .wr_data(cc_wdata),
        .rd_en(1'b1), .rd_addr(cc_ra), .rd_data(cc_rd)
    );

    // +3: unpacked; the word's column and column - row (of lane 0)
    wire [383:0] xa3, xb3;
    sru_unpack #(.IEEE(F16_IEEE)) u_ua (.clk(clk), .in_data(fa2), .out_data(xa3));
    generate
    if (HAS_B != 0) begin : g_ub
        sru_unpack #(.IEEE(F16_IEEE)) u_ub (.clk(clk), .in_data(ib2), .out_data(xb3));
    end else begin : g_noub
        assign xb3 = 384'd0;
    end
    endgenerate
    reg  signed [19:0] cw3, dw3;
    always @(posedge clk) begin
        cw3 <= $signed({8'd0, ih2}) * 4 + $signed(c_coff);
        dw3 <= ($signed({8'd0, ih2}) * 4 + $signed(c_coff))
             - ($signed({4'd0, ig2}) * 4 + $signed(c_roff));
    end

    // +4: the mask -- col - row > DHI, or col >= CLIM, takes MVAL. A lane's
    // col - row is the word's plus c - r in [-3, 3], its col the word's plus
    // c: 7 + 4 compares serve the 16 lanes.
    wire [6:0] md;
    wire [3:0] mc;
    generate
    for (gk = 0; gk < 7; gk = gk + 1) begin : g_md
        assign md[gk] = (dw3 > ($signed({{4{c_dhi[15]}}, c_dhi}) - (gk - 3)));
    end
    for (gk = 0; gk < 4; gk = gk + 1) begin : g_mc
        assign mc[gk] = (cw3 >= ($signed({4'd0, c_clim}) - gk));
    end
    endgenerate
    reg  [383:0] x4, b4;
    always @(posedge clk) begin
        for (q = 0; q < 16; q = q + 1) begin
            x4[q*24 +: 24] <= (c_mask && (md[(q % 4) - (q / 4) + 3] || mc[q % 4]))
                            ? c_mval : xa3[q*24 +: 24];
        end
        b4 <= xb3;
        if (rst) m4 <= 5'd0; else m4 <= im3;
    end

    // ======================================================== the chain
    // row scalars by parity: W[par][row] = {R2, R1, R0}
    reg  [71:0]  W0 [0:3];
    reg  [71:0]  W1 [0:3];
    wire [287:0] wv0 = {W0[3], W0[2], W0[1], W0[0]};
    wire [287:0] wv1 = {W1[3], W1[2], W1[1], W1[0]};

    wire er2 = (HAS_R2 != 0) && `SRU_P_R2EN(cur);

    // ---- the pool ----
    wire         pl_restart;
    wire         pl_ov;
    wire [383:0] pl_od;
    wire [3:0]   pl_om;
    wire         fin_dv, fin_dov;          // the finalise's op through lane 0
    wire         fin_dfn, fin_dhalf;
    wire [23:0]  fin_da, fin_db, fin_dc, fin_dout;
    generate
    if (F_LANES != 0) begin : g_pool
        sru_pool #(.MODEL(MODEL), .F_LANES(F_LANES), .HAS_FN(HAS_FN), .TAB(TAB),
                   .HAS_B(HAS_B), .H_TAPS(H_TAPS), .HAS_MANT(HAS_MANT),
                   .FIN_RCP(FIN_RCP)) u_pool (
            .clk(clk), .rst(rst),
            .restart(pl_restart),
            .nops(nops_c), .opbase(`SRU_P_OPBASE(cur)),
            .op_we(op_we), .op_waddr(cfg_addr[5:0]), .op_wdata(cfg_wdata),
            .tab_we(tab_we), .tab_waddr(tab_waddr), .tab_wdata(tab_wdata),
            .want(pl_want), .take(issue && use_pl),
            .take_meta({wi[8:0], d_first, d_last, par, emit_p}),
            .x4(x4), .b4(b4), .wv0(wv0), .wv1(wv1),
            .col0(c_col0), .cc_raddr(cc_ra), .cc_rdata(cc_rd),
            .out_valid(pl_ov), .out_data(pl_od), .out_meta(pl_om),
            .dir_valid(fin_dv), .dir_fn(fin_dfn), .dir_half(fin_dhalf),
            .dir_a(fin_da), .dir_b(fin_db), .dir_c(fin_dc),
            .dir_ov(fin_dov), .dir_out(fin_dout)
        );
    end else begin : g_nopool
        assign pl_want  = 1'b0;
        assign pl_ov    = 1'b0;
        assign pl_od    = 384'd0;
        assign pl_om    = 4'd0;
        assign cc_ra    = 9'd0;
        assign fin_dov  = 1'b0;
        assign fin_dout = 24'd0;
    end
    endgenerate
    wire [383:0] x7 = use_pl ? pl_od : x4;
    wire [4:0]   m7 = use_pl ? {pl_om, pl_ov} : m4;

    // ---- R2 and its rounding ----
    wire        s2_ov;
    wire [95:0] s2_rows;
    generate
    if (HAS_R2 != 0) begin : g_r2
        wire        r2_ov;
        wire [231:0] r2_out;
        sru_red #(.KIND("sum")) u_r2 (
            .clk(clk), .rst(rst), .in_valid(m7[0] && er2), .in_first(m7[4]),
            .in_last(m7[3]), .in_data(x7), .out_valid(r2_ov), .out(r2_out)
        );
        sru_sum2e8 u_s2e (
            .clk(clk), .rst(rst), .in_valid(r2_ov), .in_rows(r2_out),
            .out_valid(s2_ov), .out_rows(s2_rows)
        );
    end else begin : g_nor2
        assign s2_ov = 1'b0;
        assign s2_rows = 96'd0;
    end
    endgenerate

    // ---- FP16 (v2_cvt's two halves), then MXFP7 or the out FIFO ----
    reg  [495:0] mid8;
    reg  [255:0] h9;
    reg  [4:0]   m8, m9;
    wire [495:0] mid_w;
    wire [255:0] h_w;
    genvar gj;
    generate
    for (gj = 0; gj < 16; gj = gj + 1) begin : g_cvt
        if (F16_IEEE != 0) begin : g_ieee
            v2_e8_to_f16_s1 u_c1 (.e8(x7[gj*24 +: 24]), .mid(mid_w[gj*31 +: 31]));
            v2_e8_to_f16_s2 u_c2 (.mid(mid8[gj*31 +: 31]), .f16(h_w[gj*16 +: 16]));
        end else begin : g_acc
            sru_e8f16_acc_s1 u_c1 (.e8(x7[gj*24 +: 24]), .mid(mid_w[gj*31 +: 20]));
            sru_e8f16_acc_s2 u_c2 (.mid(mid8[gj*31 +: 20]), .f16(h_w[gj*16 +: 16]));
            assign mid_w[gj*31 + 20 +: 11] = 11'd0;
        end
    end
    endgenerate
    always @(posedge clk) begin
        mid8 <= mid_w;
        h9   <= h_w;
        if (rst) begin
            m8 <= 5'd0; m9 <= 5'd0;
        end else begin
            m8 <= m7; m9 <= m8;
        end
    end

    wire         mx_ov;
    wire [255:0] mx_od;
    generate
    if (HAS_MX7 != 0) begin : g_mx7
        sru_mx7 #(.MUL_DSP(MX_DSP)) u_mx7 (
            .clk(clk), .rst(rst), .b_layout(c_out == 2'd3),
            .in_valid(m9[0] && m9[1] && mx), .in_first(m9[4]), .in_data(h9),
            .out_valid(mx_ov), .out_data(mx_od)
        );
    end else begin : g_nomx7
        assign mx_ov = 1'b0;
        assign mx_od = 256'd0;
    end
    endgenerate

    wire         push   = mx ? mx_ov : (m9[0] && m9[1]);
    wire [255:0] push_d = mx ? mx_od : h9;

    // ---- the out FIFO ----
    reg  [OAW:0] owp, orp;
    wire [255:0] ord;
    kohaku_sdpram #(.WIDTH(256), .DEPTH(OUT_DEPTH), .MEM_PRIM("distributed"), .READ_LAT(0)) u_of (
        .clk(clk), .wr_en(push), .wr_addr(owp[OAW-1:0]), .wr_data(push_d),
        .rd_en(1'b1), .rd_addr(orp[OAW-1:0]), .rd_data(ord)
    );
    assign o_valid = (owp != orp);
    assign o_data  = ord;
    // the occupancy is a register of its own, not owp - orp: the shell's
    // burst-header and credit logic starts from it
    reg  [OAW:0] occ;
    assign o_count = {{(7-OAW){1'b0}}, occ};
    wire   pop = o_valid && o_pop;

    // ======================================================== row state RAM
    reg         rs_wen;
    reg  [8:0]  rs_wa, rs_ra;
    reg  [71:0] rs_wd;
    wire [71:0] rs_q;
    kohaku_sdpram #(.WIDTH(72), .DEPTH(512), .MEM_PRIM("block"), .READ_LAT(2)) u_rs (
        .clk(clk), .wr_en(rs_wen || (rs_we && !busy)), .wr_addr(rs_wen ? rs_wa : rs_waddr),
        .wr_data(rs_wen ? rs_wd : rs_wdata),
        .rd_en(1'b1), .rd_addr(busy ? rs_ra : rs_raddr), .rd_data(rs_q)
    );
    assign rs_rdata = rs_q;

    // ======================================================== statistics
    // R1 lands once a sub-row, in sub-row order (g1). R2 lands once a pass
    // that sums, so its sub-row parity rides a FIFO from the last word in.
    reg  [15:0] g1;
    reg  [3:0]  r2pq;                  // parities of sums in flight, oldest at [0]
    reg  [2:0]  r2pn;
    wire        r2_par = r2pq[0];
    reg  [23:0] st1_0 [0:3];
    reg  [23:0] st1_1 [0:3];
    reg  [23:0] st2_0 [0:3];
    reg  [23:0] st2_1 [0:3];
    reg  [1:0]  st1_rdy, st2_rdy;

    // ======================================================== finalise
    // A step issues the 4 rows, waits for the 4 results, writes them back: no
    // step reads a result before it lands. ADD/SUB/MUL/FMA run on pool lane 0
    // (the pool is empty during a finalise); MOV/MAX/MIN on a compare-select
    // here. MUL adds a zero of the product's sign, so a zero product keeps it.
    // A profile with no pool finalises MOV/MAX/MIN only.
    reg  [23:0] T0 [0:3];
    reg  [23:0] T1 [0:3];
    reg  [3:0]  fpc, fend;
    reg  [2:0]  fr, fw;
    reg         fbusy;
    wire [31:0] fins  = cfg[`SRU_FIN_BASE + fpc];
    wire [4:0]  f_op  = `SRU_F_OP(fins);
    wire [1:0]  f_dst = `SRU_F_DST(fins);
    wire [3:0]  f_a   = `SRU_F_A(fins);
    wire [3:0]  f_b   = `SRU_F_B(fins);
    wire [3:0]  f_c   = `SRU_F_C(fins);

    // the 10 sources of row fr of the current sub-row
    wire [1:0]  frr = fr[1:0];
    wire [71:0] fw_row = par ? W1[frr] : W0[frr];
    wire [23:0] fs_t   = par ? T1[frr] : T0[frr];
    wire [23:0] fs_s1  = par ? st1_1[frr] : st1_0[frr];
    wire [23:0] fs_s2  = par ? st2_1[frr] : st2_0[frr];
    wire [23:0] fsrc [0:15];
    assign fsrc[0]  = fw_row[23:0];
    assign fsrc[1]  = fw_row[47:24];
    assign fsrc[2]  = fw_row[71:48];
    assign fsrc[3]  = fs_t;
    assign fsrc[4]  = fs_s1;
    assign fsrc[5]  = fs_s2;
    assign fsrc[6]  = `SRU_G_K0;
    assign fsrc[7]  = `SRU_G_K1;
    assign fsrc[8]  = `SRU_G_K2;
    assign fsrc[9]  = `SRU_G_K3;
    generate
    for (gj = 10; gj < 16; gj = gj + 1) begin : g_fz
        assign fsrc[gj] = 24'd0;
    end
    endgenerate

    wire        fa_v = fbusy && (fr < 3'd4);
    reg  [23:0] fa_a, fa_b, fa_c;
    reg  [4:0]  fa_op;
    reg         fa_vr;
    always @(posedge clk) begin
        fa_a  <= fsrc[f_a];
        fa_b  <= fsrc[f_b];
        fa_c  <= fsrc[f_c];
        fa_op <= f_op;
        if (rst) fa_vr <= 1'b0; else fa_vr <= fa_v;
    end
    localparam [4:0] F_MOV = 5'd0, F_ADD = 5'd3, F_SUB = 5'd4, F_MUL = 5'd5,
                     F_MAX = 5'd8, F_MIN = 5'd9, F_RCP = 5'd10, F_RSQ = 5'd11;
    localparam [23:0] E8_ONE = 24'h3F8000;
    // RCP / RSQRT run on lane 0's mantissa ROM; a build without it moves A
    wire        f_rcp = (fa_op == F_RCP) || (fa_op == F_RSQ);
    wire        f_mov = (fa_op == F_MOV) || ((FIN_RCP == 0) && f_rcp);
    wire        f_sel = f_mov || (fa_op == F_MAX) || (fa_op == F_MIN);

    // compare-select: the R1/R2 sign-magnitude key; a zero leaves as +0
    wire [23:0] ka = fa_a[23] ? {1'b0, ~fa_a[22:0]} : {1'b1, fa_a[22:0]};
    wire [23:0] kb = fa_b[23] ? {1'b0, ~fa_b[22:0]} : {1'b1, fa_b[22:0]};
    wire        pick_a = f_mov || ((fa_op == F_MAX) ? (ka >= kb) : (ka <= kb));
    wire [23:0] sel_w  = pick_a ? fa_a : fa_b;
    reg         sel_v;
    reg  [23:0] sel_o;
    always @(posedge clk) begin
        if (rst) sel_v <= 1'b0; else sel_v <= fa_vr && f_sel;
        sel_o <= (sel_w[22:15] == 8'd0) ? 24'd0 : sel_w;
    end

    assign fin_dv    = fa_vr && !f_sel;
    assign fin_dfn   = f_rcp;
    assign fin_dhalf = (fa_op == F_RSQ);
    assign fin_da    = fa_a;
    assign fin_db = ((fa_op == F_ADD) || (fa_op == F_SUB)) ? E8_ONE : fa_b;
    assign fin_dc = (fa_op == F_MUL) ? {fa_a[23] ^ fa_b[23], 23'd0}
                  : (fa_op == F_SUB) ? {~fa_c[23], fa_c[22:0]} : fa_c;

    wire        fo_v = sel_v || fin_dov;
    wire [23:0] fo   = sel_v ? sel_o : fin_dout;

    // ======================================================== sequencer
    wire [15:0] rowg       = {7'd0, c_row0} + {g[13:0], 2'b00};   // first row of sub-row g
    reg  [11:0] infl;
    reg  [11:0] infl_par0, infl_par1;
    wire        pipe_empty = (infl == 12'd0);
    // held while idle and through passes of no ops too: no program is loaded
    assign pl_restart = (st == S_IDLE) || !use_pl || ((st == S_PASS) && pipe_empty);
    wire [3:0]  finlen_p   = `SRU_P_FINLEN(p);
    wire [3:0]  finbase_p  = `SRU_P_FINBASE(p);
    wire        last_pass  = (p == (c_buf ? c_npass : 2'd0));
    wire        par_clear  = par ? (infl_par1 == 12'd0) : (infl_par0 == 12'd0);
    wire        st1_here   = par ? st1_rdy[1] : st1_rdy[0];
    wire        st2_here   = par ? st2_rdy[1] : st2_rdy[0];
    wire        filled_here = par ? filled[1] : filled[0];

    always @(posedge clk) begin
        if (rst) begin
            st <= S_IDLE; busy <= 1'b0; done <= 1'b0;
            gf <= 16'd0; wf <= 12'd0; filled <= 2'b00;
            g <= 16'd0; p <= 2'd0; wi <= 12'd0; cur <= 2'd0;
            infl <= 12'd0; infl_par0 <= 12'd0; infl_par1 <= 12'd0;
            res <= {OCW{1'b0}};
            owp <= {(OAW+1){1'b0}}; orp <= {(OAW+1){1'b0}}; occ <= {(OAW+1){1'b0}};
            g1 <= 16'd0; st1_rdy <= 2'b00; st2_rdy <= 2'b00;
            r2pn <= 3'd0;
            fbusy <= 1'b0; rs_wen <= 1'b0;
        end else begin
            done   <= 1'b0;
            rs_wen <= 1'b0;

            // ---- fill side ----
            if (fill_take) begin
                if (wf == c_nw - 12'd1) begin
                    wf <= 12'd0;
                    filled[fh] <= 1'b1;
                    gf <= gf + 16'd1;
                end else begin
                    wf <= wf + 12'd1;
                end
            end

            // ---- statistics landing, in sub-row order ----
            if (r1_ovalid) begin
                for (q = 0; q < 4; q = q + 1) begin
                    if (g1[0]) st1_1[q] <= f16e8k(r1_out[q*58 +: 16], F16_IEEE);
                    else       st1_0[q] <= f16e8k(r1_out[q*58 +: 16], F16_IEEE);
                end
                st1_rdy[g1[0]] <= 1'b1;
                g1 <= g1 + 16'd1;
            end
            if (s2_ov) begin
                for (q = 0; q < 4; q = q + 1) begin
                    if (r2_par) st2_1[q] <= s2_rows[q*24 +: 24];
                    else        st2_0[q] <= s2_rows[q*24 +: 24];
                end
                st2_rdy[r2_par] <= 1'b1;
            end
            // the parity FIFO: push at a summed sub-row's last word, pop as it lands
            begin : r2pf
                reg       push2;
                push2 = m7[0] && er2 && m7[3];
                case ({push2, s2_ov})
                    2'b10: begin r2pq[r2pn] <= m7[2]; r2pn <= r2pn + 3'd1; end
                    2'b01: begin r2pq <= {1'b0, r2pq[3:1]}; r2pn <= r2pn - 3'd1; end
                    2'b11: begin
                        r2pq <= {1'b0, r2pq[3:1]};
                        r2pq[r2pn - 3'd1] <= m7[2];
                    end
                    default: ;
                endcase
            end

            // ---- in flight and the out reservation ----
            infl <= infl + (issue ? 12'd1 : 12'd0) - (m7[0] ? 12'd1 : 12'd0);
            infl_par0 <= infl_par0 + ((issue && !par) ? 12'd1 : 12'd0)
                       - ((m7[0] && !m7[2]) ? 12'd1 : 12'd0);
            infl_par1 <= infl_par1 + ((issue && par) ? 12'd1 : 12'd0)
                       - ((m7[0] && m7[2]) ? 12'd1 : 12'd0);
            res <= res + ((issue && emit_p) ? 1 : 0) - (pop ? (mx ? 2 : 1) : 0);
            if (push) owp <= owp + 1'b1;
            occ <= occ + (push ? 1'b1 : 1'b0) - (pop ? 1'b1 : 1'b0);
            if (pop)  orp <= orp + 1'b1;

            // ---- finalise ----
            if (fa_v) fr <= fr + 3'd1;
            if (fo_v) begin
                case (f_dst)
                    2'd0: if (par) W1[fw[1:0]][23:0]  <= fo; else W0[fw[1:0]][23:0]  <= fo;
                    2'd1: if (par) W1[fw[1:0]][47:24] <= fo; else W0[fw[1:0]][47:24] <= fo;
                    2'd2: if (par) W1[fw[1:0]][71:48] <= fo; else W0[fw[1:0]][71:48] <= fo;
                    default: if (par) T1[fw[1:0]] <= fo; else T0[fw[1:0]] <= fo;
                endcase
                fw <= fw + 3'd1;
            end
            if (fbusy && (fw == 3'd4)) begin
                if (fpc + 4'd1 == fend) begin
                    fbusy <= 1'b0;
                end else begin
                    fpc <= fpc + 4'd1;
                    fr  <= 3'd0;
                    fw  <= 3'd0;
                end
            end

            // ---- the sequencer ----
            case (st)
                S_IDLE: if (start) begin
                    busy <= 1'b1;
                    gf <= 16'd0; wf <= 12'd0; filled <= 2'b00;
                    g <= 16'd0; g1 <= 16'd0;
                    st1_rdy <= 2'b00; st2_rdy <= 2'b00;
                    st <= S_SR;
                end
                S_SR: if (g == c_nsr) begin
                    st <= S_DRAIN;
                end else if ((!c_buf || filled_here) && par_clear
                             && (!c_buf || !c_r1 || st1_here)) begin
                    ld <= 3'd0;
                    st <= S_LOAD;
                end
                S_LOAD: begin
                    // rows rowg..rowg+3; each answers 3 cycles after its address
                    rs_ra <= rowg[8:0] + {6'd0, ld};
                    if (ld >= 3'd3) begin
                        if (par) W1[ld - 3'd3] <= rs_q; else W0[ld - 3'd3] <= rs_q;
                    end
                    ld <= ld + 3'd1;
                    if (ld == 3'd6) begin
                        p <= 2'd0;
                        if (c_buf) begin
                            fin_then_pass <= 1'b1;   // pass 0 was the fill
                            st <= S_FIN;
                        end else begin
                            st <= S_PASS;
                        end
                    end
                end
                S_FIN: begin
                    if (finlen_p == 4'd0) begin
                        if (fin_then_pass) begin
                            p  <= p + 2'd1;
                            st <= S_PASS;
                        end else begin
                            ld <= 3'd0;
                            st <= S_STORE;
                        end
                    end else if (!fbusy && pipe_empty) begin
                        // the pool is empty: lane 0 is the finalise's
                        fbusy <= 1'b1;
                        fpc   <= finbase_p;
                        fend  <= finbase_p + finlen_p;
                        fr    <= 3'd0;
                        fw    <= 3'd0;
                        st    <= S_PWAIT;
                    end
                end
                S_PASS: if ((cur == p) || pipe_empty) begin
                    cur <= p;
                    wi  <= 12'd0;
                    st  <= S_ISSUE;
                end
                S_ISSUE: if (issue) begin
                    wi <= wi + 12'd1;
                    if (wi == c_nw - 12'd1) begin
                        st <= S_NEXT;
                    end
                end
                S_NEXT: begin
                    if (finlen_p != 4'd0) begin
                        // wait for this sub-row's statistics
                        if ((!`SRU_P_R2EN(p) || st2_here) && (c_buf || !c_r1 || st1_here)) begin
                            fin_then_pass <= !last_pass;
                            st <= S_FIN;
                        end
                    end else if (last_pass) begin
                        ld <= 3'd0;
                        st <= S_STORE;
                    end else begin
                        p  <= p + 2'd1;
                        st <= S_PASS;
                    end
                end
                S_PWAIT: if (!fbusy) begin
                    // the finalise consumed this sub-row's statistics
                    if ((p == 2'd0 && c_buf) || !c_buf) st1_rdy[par] <= 1'b0;
                    if (`SRU_P_R2EN(p)) st2_rdy[par] <= 1'b0;
                    if (fin_then_pass) begin
                        p  <= p + 2'd1;
                        st <= S_PASS;
                    end else begin
                        ld <= 3'd0;
                        st <= S_STORE;
                    end
                end
                S_STORE: begin
                    rs_wen <= 1'b1;
                    rs_wa  <= rowg[8:0] + {6'd0, ld};
                    rs_wd  <= par ? W1[ld[1:0]] : W0[ld[1:0]];
                    ld <= ld + 3'd1;
                    if (ld == 3'd3) begin
                        if (c_buf) filled[par] <= 1'b0;
                        g  <= g + 16'd1;
                        st <= S_SR;
                    end
                end
                S_DRAIN: if (pipe_empty && (owp == orp) && (res == {OCW{1'b0}})) begin
                    busy <= 1'b0;
                    done <= 1'b1;
                    st   <= S_IDLE;
                end
                default: st <= S_IDLE;
            endcase
        end
    end

`ifdef SRU_STATE_TRACE
    // the sequencer's state changes and each sub-row's fill completion, by cycle
    reg [3:0]  st_tq;
    reg [31:0] tcyc;
    always @(posedge clk) begin
        st_tq <= st;
        tcyc  <= rst ? 32'd0 : tcyc + 32'd1;
        if (!rst && st != st_tq) $display("SRUST %0d %m st %0d g %0d p %0d", tcyc, st, g, p);
        if (!rst && fill_take && wf == c_nw - 12'd1) $display("SRUFL %0d %m g %0d", tcyc, gf);
    end
`endif

`ifndef SYNTHESIS
    always @(posedge clk) begin
        if (!rst && s2_ov && (r2_par ? st2_rdy[1] : st2_rdy[0])) begin
            $display("%0t ERROR sru_core %m: a row sum overwrote one not yet finalised", $time);
        end
        if (!rst && r1_ovalid && (g1[0] ? st1_rdy[1] : st1_rdy[0]) && c_buf) begin
            $display("%0t ERROR sru_core %m: a row max overwrote one not yet finalised", $time);
        end
    end
`endif

endmodule

`default_nettype wire
